+    }
+    (posts, machines)
+}
+
+fn counted_read() -> Scans {
+    SCAN_READS.fetch_add(1, Ordering::Relaxed);
+    read_scans()
+}
+
+fn with_scans<T>(f: impl FnOnce(&Scans) -> T) -> T {
+    let mut g = SCANS.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
